package io.github.jesterportfolio.hearth.persistence;
import java.util.*;import java.util.concurrent.*;import java.sql.*;import javax.sql.DataSource;
import io.github.jesterportfolio.hearth.economy.*;import io.github.jesterportfolio.hearth.inventory.InventoryPayload;import io.github.jesterportfolio.hearth.survival.housing.*;
/** 소유 PG 복사본의 정책·위치·권한 경합, SQL 실패, 데이터 보존. */
public final class RpgDatabaseChecks {
 static <T>T await(CompletionStage<T> f)throws Exception{return f.toCompletableFuture().get(12,TimeUnit.SECONDS);}
 static void check(boolean b,String name){if(!b)throw new IllegalStateException(name);System.out.println("HEARTH_RPG_DB_CHECK PASS "+name);System.out.flush();}
 static void reject(CompletionStage<?> f)throws Exception{try{await(f);throw new IllegalStateException("EXPECTED_REJECTION");}catch(ExecutionException expected){}}
 static String result(CompletionStage<?> f)throws Exception{return await(f.handle((v,e)->e==null?"OK":io.github.jesterportfolio.hearth.inventory.InventorySaveSession.code(e)));}
 public static void run(DataSource source,Connection c)throws Exception{
  var p=new Properties();try(var in=RpgDatabaseChecks.class.getResourceAsStream("/economy-demo.properties")){p.load(in);}p.setProperty("fixture-balance","0");var content=EconomyContent.parse(p);var db=PostgresProgressStore.forModules(source,f->{});var e=new EconomyStore(db,content);await(e.migrate());await(e.migrate());check(true,"E010_idempotent_upgrade_preserves_prior_checksums");
  UUID realm=UUID.randomUUID(),other=UUID.randomUUID(),publicWorld=UUID.randomUUID();await(e.openNativeRealm(realm,UUID.randomUUID(),"7".repeat(64),1,true));await(e.openNativeRealm(other,UUID.randomUUID(),"8".repeat(64),1,true));var owner=e.context(realm,UUID.randomUUID());var friend=e.context(realm,UUID.randomUUID());var payload=InventoryPayload.pack(new byte[41][]);await(e.ensureAccount(owner,payload));await(e.ensureAccount(friend,payload));
  var geometry=new HousingSettings(new HousingSettings.Catalog("rpg",List.of(new HousingSettings.Tier("small",32,0))),true,true,8,2,300,8,List.of(new HousingSettings.Plot("one",16,0,16,32)));var housing=new HousingStore(db,e,realm,geometry);await(housing.open());await(housing.claimPlot(owner,()->true));var request=await(housing.reserve(owner,UUID.randomUUID(),0,-1,()->true));UUID houseWorld=UUID.randomUUID();await(housing.prepared(owner,request,houseWorld));await(housing.commit(owner,request,()->true,EconomyStore.Probe.NONE));var house=await(housing.activate(owner,request));var r=new RpgStore(db,e,realm,publicWorld,0,64,0,geometry);
  var extra=new RpgStore.Extra("novice","hearth_survival:novice",UUID.randomUUID(),42);await(r.bindExtra(extra));await(r.bindExtra(extra));reject(r.bindExtra(new RpgStore.Extra("novice",extra.key(),UUID.randomUUID(),42)));check(await(r.snapshot()).extras().equals(List.of(extra)),"immutable_extra_world_identity_without_changing_native_binding");reject(e.requireNoRpg(realm));
  reject(r.pvp(friend,house.id(),true,-1));var a=r.pvp(owner,house.id(),true,-1);var b=r.pvp(owner,house.id(),false,-1);check(Set.of(result(a),result(b)).equals(Set.of("OK","RPG_CAS")),"owner_only_PvP_and_concurrent_CAS_one_winner");
  var home=new RpgStore.Home(owner.playerId(),publicWorld,16.5,65,.5,90,0,0);await(r.home(owner,home,-1));reject(r.home(friend,home,0));var h1=r.home(owner,home,0);var h2=r.home(owner,home,0);check(Set.of(result(h1),result(h2)).equals(Set.of("OK","RPG_CAS")),"home_owner_and_revision_guards_preserve_native_inventory");
  var acl=new RpgStore.Acl(UUID.randomUUID(),owner.playerId(),publicWorld,16,64,0,17,64,0,RpgStore.Mode.LIST,Set.of(friend.playerId()),0);await(r.object(owner,acl,-1));reject(r.object(friend,acl,0));reject(r.object(owner,new RpgStore.Acl(UUID.randomUUID(),owner.playerId(),publicWorld,15,64,0,15,64,0,RpgStore.Mode.PUBLIC,Set.of(),0),-1));check(await(r.snapshot()).objects().getFirst().permits(friend.playerId()),"plot_bounds_and_named_interaction_do_not_grant_plot_build_membership");
  var privateAcl=new RpgStore.Acl(UUID.randomUUID(),owner.playerId(),houseWorld,0,64,0,0,64,0,RpgStore.Mode.PRIVATE,Set.of(),0);await(r.object(owner,privateAcl,-1));reject(r.object(friend,new RpgStore.Acl(UUID.randomUUID(),friend.playerId(),houseWorld,1,64,0,1,64,0,RpgStore.Mode.PUBLIC,Set.of(),0),-1));check(true,"private_house_object_owner_is_rechecked_in_PG");
  reject(r.object(owner,new RpgStore.Acl(acl.id(),owner.playerId(),houseWorld,0,64,0,0,64,0,RpgStore.Mode.PUBLIC,Set.of(),0),0));check(await(r.snapshot()).objects().stream().filter(x->x.id().equals(acl.id())).findFirst().orElseThrow().world().equals(publicWorld),"object_CAS_also_binds_original_world_and_anchor_geometry");
  var o1=r.object(owner,acl,0);var o2=r.object(owner,acl,0);check(Set.of(result(o1),result(o2)).equals(Set.of("OK","RPG_CAS")),"object_concurrent_revision_has_single_winner");
  try(var s=c.createStatement()){s.execute("CREATE FUNCTION hearth_economy.reject_rpg_fixture() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'rpg fixture failure' USING ERRCODE='23514'; END $$");s.execute("CREATE TRIGGER reject_rpg_fixture BEFORE UPDATE ON hearth_economy.object_acl FOR EACH ROW EXECUTE FUNCTION hearth_economy.reject_rpg_fixture()");}reject(r.object(owner,acl,1));check(await(r.snapshot()).objects().stream().filter(x->x.id().equals(acl.id())).findFirst().orElseThrow().revision()==1,"real_SQL_failure_preserves_acl_and_revision");try(var s=c.createStatement()){s.execute("DROP TRIGGER reject_rpg_fixture ON hearth_economy.object_acl");s.execute("DROP FUNCTION hearth_economy.reject_rpg_fixture()");}
  var current=await(r.snapshot()).objects().stream().filter(x->x.id().equals(acl.id())).findFirst().orElseThrow();await(r.removeObject(owner,current));check(await(r.snapshot()).objects().stream().anyMatch(x->x.id().equals(acl.id())&&x.mode()==RpgStore.Mode.REMOVED),"removal_keeps_owned_region_cleanup_tombstone");
  var ca=r.reserveSkill(owner,"hearth/metallurgy",1000,2000);var cb=r.reserveSkill(owner,"hearth/metallurgy",1000,2000);check(Set.of(result(ca),result(cb)).equals(Set.of("OK","RPG_CAS")),"active_skill_reserves_one_durable_cooldown_before_effect");reject(r.reserveSkill(e.context(other,owner.playerId()),"hearth/metallurgy",2000,3000));reject(r.pvp(new ServerProgressAccess().forVerifiedServerLink(realm,owner.playerId()),house.id(),false,0));check(await(r.cooldowns(owner)).equals(Map.of("hearth/metallurgy",2000L))&&await(e.account(owner)).inventory().payload().equals(payload),"foreign_issuer_realm_denied_and_original_inventory_preserved");
  String hash;try(var s=c.createStatement();var rs=s.executeQuery("SELECT checksum FROM hearth_economy.version WHERE version=10")){rs.next();hash=rs.getString(1);}try(var s=c.createStatement()){s.execute("UPDATE hearth_economy.version SET checksum='rpg-fixture-mismatch' WHERE version=10");}var mismatch=PostgresProgressStore.forModules(source,f->{});reject(new EconomyStore(mismatch,content).migrate());await(mismatch.closeAsync());try(var s=c.prepareStatement("UPDATE hearth_economy.version SET checksum=? WHERE version=10")){s.setString(1,hash);s.executeUpdate();}check(await(r.snapshot()).extras().equals(List.of(extra)),"E010_checksum_mismatch_never_rewrites_saved_state");await(db.closeAsync());
 }
}
